const fs = require("fs").promises;
const path = require("path");

async function ecrireNote(dossier, texte) {
  const chemin = path.join(dossier, "note.txt");
  await fs.writeFile(chemin, texte);
  return chemin;
}

const fs = require("fs").promises;

async function compterLignes(chemin) {
  const texte = await fs.readFile(chemin, "utf8");
  return texte.split("\n").filter(l => l.trim() !== "").length;
}

