const fs = require("fs").promises;

async function lireOuDefaut(chemin, defaut) {
  try {
    return await fs.readFile(chemin, "utf8");
  } catch (erreur) {
    if (erreur.code === "ENOENT") return defaut;
    throw erreur;
  }
}

